#define LLVM_LIBC_HDR_TYPES_FILE_H

#ifdef LIBC_FULL_BUILD

#include "include/llvm-libc-types/FILE.h"

#else // Overlay mode

#include "hdr/stdio_overlay.h"

#endif // LIBC_FULL_BUILD

