    libc.src.mathvec.sqrtf
    libc.src.mathvec.tanf
    libc.src.mathvec.tanhf
    libc.src.mathvec.tanpif
  )
endif()

set(TARGET_LLVMLIBC_ENTRYPOINTS
  ${TARGET_LIBC_ENTRYPOINTS}
  ${TARGET_LIBM_ENTRYPOINTS}
  ${TARGET_LIBMVEC_ENTRYPOINTS}
)
